def solve_n_queens(n=26):
    col = [False] * n
    diag1 = [False] * (2*n-1)
    diag2 = [False] * (2*n-1)
    pos = [-1] * n

    def backtrack(row):
        if row == n:
            return True
        for c in range(n):
            if not col[c] and not diag1[row + c] and not diag2[row - c + n - 1]:
                col[c] = diag1[row + c] = diag2[row - c + n - 1] = True
                pos[row] = c
                if backtrack(row + 1):
                    return True
                col[c] = diag1[row + c] = diag2[row - c + n - 1] = False
        return False

    if backtrack(0):
        return pos
    return None

solution = solve_n_queens()
print(solution)
print(len(solution) if solution else "None")
